#!/usr/bin/env python3
"""What `folder_merge.py` decides, on fixed data.

Run: python3 -m unittest discover -s .agents/skills/folder-merge -p 'test_*.py'
"""
import base64
import datetime
import json
import unittest
from unittest import mock

import folder_merge
import pr_status

SETUP = {"USER": "human", "AGENT": "human-agents", "ADOPTED_PRS": "",
         "AGENT_FOOTERS": ["Generated by Test Harness"]}
NOW = datetime.datetime(2026, 1, 3, 12, 0, tzinfo=datetime.timezone.utc)
SHA = "a" * 40
REPO = "owner/pages"


def status(**fields):
    base = {"pr": f"{REPO}#1", "sha": SHA, "branch": "page", "title": "t",
            "draft": True, "mergeable": True, "base": "main",
            "default": "main", "ran": True, "checks": (["lint"], [], []),
            "threads": ([], []), "approved": True, "hours": 30, "hold": False,
            "boxes": 0, "unanswered": []}
    return {**base, **fields}


def comment(login, at, body="ok", kind="User"):
    return {"user": {"login": login, "type": kind}, "body": body,
            "created_at": at}


class Outside(unittest.TestCase):

    def test_every_path_in_the_folder(self):
        files = [{"filename": "content/me/a.md"},
                 {"filename": "content/me/b/c.py"}]
        self.assertEqual(folder_merge.outside(files, "me"), [])

    def test_a_rename_counts_on_both_sides(self):
        files = [{"filename": "content/me/a.md",
                  "previous_filename": "content/you/a.md"}]
        self.assertEqual(folder_merge.outside(files, "me"),
                         ["content/you/a.md"])

    def test_a_folder_that_only_starts_the_same_is_outside(self):
        files = [{"filename": "content/me-too/a.md"}]
        self.assertEqual(folder_merge.outside(files, "me"),
                         ["content/me-too/a.md"])


class Approved(unittest.TestCase):

    def review(self, login, state):
        return {"user": {"login": login}, "state": state}

    def test_an_approval_counts_whoever_gave_it(self):
        self.assertTrue(folder_merge.approved(
            [self.review("app[bot]", "APPROVED")]))

    def test_a_dismissed_approval_does_not(self):
        self.assertFalse(folder_merge.approved([
            self.review("app[bot]", "APPROVED"),
            self.review("app[bot]", "DISMISSED")]))

    def test_changes_requested_by_anyone_wins(self):
        self.assertFalse(folder_merge.approved([
            self.review("app[bot]", "APPROVED"),
            self.review("human", "CHANGES_REQUESTED")]))

    def test_a_comment_review_decides_nothing(self):
        self.assertTrue(folder_merge.approved([
            self.review("app[bot]", "APPROVED"),
            self.review("human", "COMMENTED")]))


class Holds(unittest.TestCase):

    def test_the_body_says_so(self):
        pull = {"body": "Not to merge automatically: waits for a read."}
        self.assertTrue(folder_merge.holds(pull, []))

    def test_an_added_line_says_so(self):
        files = [{"patch": "@@\n+This page is not to be merged automatically"}]
        self.assertTrue(folder_merge.holds({"body": None}, files))

    def test_a_removed_line_does_not(self):
        files = [{"patch": "@@\n-not to merge automatically\n+fine"}]
        self.assertFalse(folder_merge.holds({"body": ""}, files))


class LastPush(unittest.TestCase):
    commit = {"commit": {"committer": {"date": "2026-01-01T06:00:00Z"}}}

    def at(self, hour):
        return datetime.datetime(2026, 1, 2, hour, 0,
                                 tzinfo=datetime.timezone.utc)

    def test_a_commit_pushed_a_day_late_counts_from_its_first_check(self):
        runs = [{"started_at": "2026-01-02T09:00:00Z"},
                {"started_at": "2026-01-02T08:00:00Z"}]
        self.assertEqual(folder_merge.last_push(self.commit, runs, []),
                         self.at(8))

    def test_a_later_run_on_the_same_head_does_not_move_it(self):
        runs = [{"started_at": "2026-01-02T08:00:00Z"},
                {"started_at": "2026-01-02T20:00:00Z"}]
        self.assertEqual(folder_merge.last_push(self.commit, runs, []),
                         self.at(8))

    def test_a_force_push_back_to_an_old_head_counts(self):
        runs = [{"started_at": "2026-01-02T08:00:00Z"}]
        events = [{"event": "committed"},
                  {"event": "head_ref_force_pushed",
                   "created_at": "2026-01-02T11:00:00Z"}]
        self.assertEqual(folder_merge.last_push(self.commit, runs, events),
                         self.at(11))

    def test_no_run_leaves_the_commit_date(self):
        self.assertEqual(
            folder_merge.last_push(self.commit, [{"started_at": None}], []),
            datetime.datetime(2026, 1, 1, 6, 0, tzinfo=datetime.timezone.utc))


class Unanswered(unittest.TestCase):
    pushed = datetime.datetime(2026, 1, 2, 6, 0, tzinfo=datetime.timezone.utc)

    def test_a_human_after_the_push(self):
        found = folder_merge.unanswered(
            [comment("human", "2026-01-02T07:00:00Z")], self.pushed, SETUP)
        self.assertEqual(found, ["human"])

    def test_before_the_push_is_answered_by_it(self):
        found = folder_merge.unanswered(
            [comment("human", "2026-01-02T05:00:00Z")], self.pushed, SETUP)
        self.assertEqual(found, [])

    def test_the_agent_answering_does_not_clear_it(self):
        found = folder_merge.unanswered([
            comment("other", "2026-01-02T07:00:00Z"),
            comment("human-agents", "2026-01-02T08:00:00Z")],
            self.pushed, SETUP)
        self.assertEqual(found, ["other"])

    def test_the_agent_alone_is_nobody(self):
        found = folder_merge.unanswered(
            [comment("human-agents", "2026-01-02T08:00:00Z")],
            self.pushed, SETUP)
        self.assertEqual(found, [])

    def test_a_footer_on_the_user_account_is_the_agent(self):
        found = folder_merge.unanswered([comment(
            "human", "2026-01-02T07:00:00Z",
            "done\n\n_Generated by Test Harness_")], self.pushed, SETUP)
        self.assertEqual(found, [])

    def test_a_footer_on_any_other_account_is_a_person(self):
        found = folder_merge.unanswered([
            comment("human", "2026-01-02T07:00:00Z", "wait for me"),
            comment("other", "2026-01-02T08:00:00Z",
                    "ok\n\n_Generated by Test Harness_")], self.pushed, SETUP)
        self.assertEqual(found, ["human", "other"])

    def test_a_bot_is_not_counted(self):
        found = folder_merge.unanswered(
            [comment("review[bot]", "2026-01-02T07:00:00Z", kind="Bot")],
            self.pushed, SETUP)
        self.assertEqual(found, [])


class Verdict(unittest.TestCase):

    def test_a_quiet_approved_draft_merges(self):
        self.assertEqual(folder_merge.verdict(status(), 24), ("merge", []))

    def test_a_recent_push_is_active_whatever_else_holds(self):
        found = folder_merge.verdict(
            status(hours=5, mergeable=False, hold=True), 24)
        self.assertEqual(found, ("active", ["pushed 5h ago"]))

    def test_the_window_is_the_argument(self):
        self.assertEqual(folder_merge.verdict(status(hours=5), 4)[0], "merge")

    def test_blocked_reasons_are_all_listed(self):
        found = folder_merge.verdict(status(
            mergeable=False, checks=([], ["lint"], []), approved=False,
            threads=(["u"], []), base="under"), 24)
        self.assertEqual(found, ("blocked", [
            "base is under", "conflict", "failed lint", "1 thread(s) on agent",
            "no approval"]))

    def test_no_check_run_is_blocked(self):
        found = folder_merge.verdict(status(ran=False, checks=([], [], [])), 24)
        self.assertEqual(found, ("blocked", ["no check ran"]))

    def test_blocked_comes_before_ask(self):
        found = folder_merge.verdict(status(approved=False, hold=True), 24)
        self.assertEqual(found[0], "blocked")

    def test_each_doubt_asks(self):
        for fields, reason in [
                ({"hold": True}, "says not to merge automatically"),
                ({"boxes": 2}, "2 open box(es) in the body"),
                ({"threads": ([], ["u"])}, "1 thread(s) on USER"),
                ({"unanswered": ["other"]}, "comment by other after the push"),
                ({"mergeable": None}, "mergeable unknown")]:
            with self.subTest(reason):
                self.assertEqual(folder_merge.verdict(status(**fields), 24),
                                 ("ask", [reason]))


class Line(unittest.TestCase):

    def test_merge_prints_the_full_sha_and_the_draft(self):
        s = status(verdict="merge", reasons=[])
        self.assertEqual(folder_merge.line(s), f"{REPO}#1 @{SHA} page draft, "
                         "pushed 30h ago -> merge")

    def test_outside_names_one_path_and_counts_the_rest(self):
        s = {"pr": f"{REPO}#1", "sha": SHA, "branch": "page",
             "verdict": "outside", "outside": ["README.md", "x.py"]}
        self.assertEqual(folder_merge.line(s),
                         f"{REPO}#1 @{SHA} page -> outside (README.md (+1))")


class Sweep(unittest.TestCase):

    def pull(self, number, login="human-agents"):
        return {"number": number, "title": f"t{number}",
                "user": {"login": login},
                "head": {"sha": SHA, "ref": f"b{number}"}}

    def get(self, pulls, files):
        folders = base64.b64encode(json.dumps(
            {"human-agents": "me"}).encode()).decode()

        def get(repo, path, key=None):
            if path.startswith("contents/"):
                return {"content": folders}
            if path == "pulls?state=open":
                return pulls
            number = int(path.split("/")[1])
            return files[number]
        return get

    def test_only_the_agents_pulls_and_the_adopted_ones(self):
        pulls = [self.pull(1), self.pull(2, "other"), self.pull(3, "other")]
        setup = {**SETUP, "ADOPTED_PRS": f"{REPO}#3, else/where#2"}
        with mock.patch.object(pr_status, "get", self.get(pulls, {})):
            found = folder_merge.candidates(REPO, setup)
        self.assertEqual([p["number"] for p in found], [1, 3])

    def test_outside_is_decided_from_the_paths_alone(self):
        files = {1: [{"filename": "README.md"}]}
        with mock.patch.object(pr_status, "get", self.get(
                [self.pull(1)], files)), mock.patch.object(
                    pr_status, "request",
                    return_value={"default_branch": "main"}):
            rows = folder_merge.sweep(REPO, SETUP, NOW, 24)
        self.assertEqual([(s["pr"], s["verdict"]) for s in rows],
                         [(f"{REPO}#1", "outside")])

    def test_an_unread_pull_says_so_and_the_rest_are_measured(self):
        files = {1: [{"filename": "README.md"}]}
        inner = self.get([self.pull(2), self.pull(1)], files)

        def get(repo, path, key=None):
            if path == "pulls/2/files":
                raise pr_status.Unread("HTTP 502")
            return inner(repo, path, key)
        with mock.patch.object(pr_status, "get", get), mock.patch.object(
                pr_status, "request", return_value={"default_branch": "main"}):
            rows = folder_merge.sweep(REPO, SETUP, NOW, 24)
        self.assertEqual([s["verdict"] for s in rows], ["outside", "n/a"])

    def test_a_map_that_is_not_one_is_a_failed_read(self):
        for content in (b"[1, 2]", b"{not json", b'"me"'):
            body = {"content": base64.b64encode(content).decode()}
            with self.subTest(content), mock.patch.object(
                    pr_status, "get", return_value=body):
                with self.assertRaises(pr_status.Unread):
                    folder_merge.folder(REPO, "human-agents", "main")
        with mock.patch.object(pr_status, "get", return_value={}):
            with self.assertRaises(pr_status.Unread):
                folder_merge.folder(REPO, "human-agents", "main")

    def test_an_agent_with_no_folder_is_a_failed_read(self):
        empty = base64.b64encode(b"{}").decode()
        with mock.patch.object(pr_status, "get", return_value={
                "content": empty}), mock.patch.object(
                    pr_status, "request",
                    return_value={"default_branch": "main"}):
            with self.assertRaises(pr_status.Unread):
                folder_merge.sweep(REPO, SETUP, NOW, 24)


if __name__ == "__main__":
    unittest.main()
